do $$
declare
  v_course_id uuid := '1ad74fd3-6a25-452c-a4b1-668f8e3be8e6';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
  v_m3 uuid;
begin
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where course_id = v_course_id;

  insert into public.levels (course_id, title, description, order_number) values
    (v_course_id, 'CSS', 'Turn plain HTML into a real design. You will learn how styling attaches to a page and how the browser resolves conflicting rules, lay out pages properly with Flexbox and Grid, and make everything work on a phone as well as a laptop. By the end you can take any page you built in Level 2 and style it deliberately, and debug it in the browser when it misbehaves.', 3)
  returning id into v_level;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'CSS Fundamentals', 'How styling attaches to your HTML, how the browser decides which rule wins, and the box that every single element on a page actually is.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Connecting CSS to HTML', 'The three ways to attach styles to a page, why external stylesheets win, and the basic selector-property-value syntax.', 'https://www.youtube.com/watch?v=n4R2E7O-Ngo', 1,
      array['Link an external stylesheet with the <link> tag', 'Write a CSS rule using selector, property, and value', 'Explain why external stylesheets are preferred over inline styles'],
      'This level is anchored on Dave Gray''s full CSS course — start with **Chapter 1, "Start Here"**, which opens the course, then come back here. Navigate by the chapter list rather than scrubbing to a timestamp.

CSS can reach your HTML three ways: an inline `style` attribute on a single element, a `<style>` block in the `<head>`, or an external `.css` file pulled in with `<link rel="stylesheet" href="style.css">`. Use the external file. It keeps your styling in one place, so changing a colour across forty pages is one edit rather than forty, and the browser can cache it — which matters directly for a visitor on a metered mobile bundle. The syntax never changes: a selector picks what to style, then a block of `property: value;` pairs says how. Every rule you write for the rest of this Learning Path is that shape.',
      'Take a page you built in Level 2, create a `style.css` beside it, link it with the <link> tag, and turn every heading a different colour. Then try the same rule as an inline style attribute and note how much messier the HTML gets.',
      '[{"question":"Which tag links an external stylesheet?","options":["<style>","<link rel=\"stylesheet\" href=\"...\">","<css>","<script src=\"...\">"],"correct_index":1},{"question":"Why is an external stylesheet preferred?","options":["It renders faster than inline styles always","One edit updates every page, and the browser can cache the file","Inline styles don''t work in modern browsers","It is required by HTML"],"correct_index":1}]'::jsonb),
    (v_m1, 'CSS Selectors', 'Target exactly the elements you mean — by element, class, id, or by where they sit inside another element.', 'https://www.youtube.com/watch?v=n4R2E7O-Ngo', 2,
      array['Select elements by tag, class, and id', 'Explain when to use a class versus an id', 'Combine selectors to target nested elements'],
      'Watch **Chapter 2, "Selectors"** of the anchor course, which starts around 14 minutes in and runs about 20 minutes.

`p { }` styles every paragraph. `.card { }` styles every element with `class="card"`. `#header { }` styles the single element with `id="header"`. Reach for classes almost always: an id must be unique on the page, so it can''t be reused, and it carries an unhelpfully heavy specificity weight you''ll be fighting in the next lesson. You can also combine — `nav a` means "every link inside a nav" — which is how you style one region without touching identical elements elsewhere. Naming classes for what something IS (`.price`, `.warning`) rather than how it looks (`.red-text`) saves you renaming everything the day the design changes.',
      'Style a page three ways: every <li> by element, a `.highlight` class applied to two of them, and one specific item by id. Then use a descendant selector to style only the links inside your nav, leaving links elsewhere untouched.',
      '[{"question":"How do you select elements with class=\"card\"?","options":["#card",".card","card","@card"],"correct_index":1},{"question":"Why prefer a class over an id for styling?","options":["Ids don''t work in CSS","Classes are reusable and carry less specificity weight to fight later","Ids are deprecated","Classes load faster"],"correct_index":1}]'::jsonb),
    (v_m1, 'Why Your CSS Isn''t Working: Cascade, Specificity and Inheritance', 'The single most common beginner frustration, explained properly — plus a tour of the other concepts that trip people up.', 'https://www.youtube.com/watch?v=JnTPd9G6hoY', 3,
      array['Explain how the browser chooses between conflicting rules', 'Rank the specificity of element, class, and id selectors', 'Describe which properties are inherited by child elements'],
      'A change of voice for this one — Kevin Powell walks through the six concepts beginners most often get stuck on. The three that matter here come first; the later material on the box model, naming conventions and layout is a preview of what''s coming, so treat the last third as bonus rather than something you must absorb now.

When two rules target the same element, the browser resolves it in order: specificity first, then source order. An id beats a class, a class beats an element selector, and between two equally specific rules the later one wins. That is the entire explanation for nearly every "my CSS isn''t working" moment — the rule IS applying, something more specific is overriding it. Inheritance is separate: properties like `color` and `font-family` pass down to children automatically, while others like `border` do not. Learn to open DevTools and look at which rule won rather than guessing, and resist reaching for `!important` — it wins the argument today and makes the next override impossible.',
      'Write three rules targeting the same paragraph — one by element, one by class, one by id — each setting a different colour. Predict which wins before you reload, then open DevTools and confirm which rules were overridden.',
      '[{"question":"Between a class selector and an id selector targeting the same element, which wins?","options":["The class","The id","Whichever comes first","Neither applies"],"correct_index":1},{"question":"Two rules have identical specificity. Which applies?","options":["The first one written","The last one written","Both are ignored","The shorter one"],"correct_index":1}]'::jsonb),
    (v_m1, 'Colours, Units and Values', 'Naming colours in hex, rgb and hsl, and knowing when to reach for px, rem, em, or a percentage.', 'https://www.youtube.com/watch?v=n4R2E7O-Ngo', 4,
      array['Write colours as named values, hex, rgb, and hsl', 'Explain the difference between px, rem, em, and %', 'Choose an appropriate unit for font sizes and spacing'],
      'Two consecutive chapters of the anchor course cover this — **Chapter 3, "Colors"** (around 34 minutes in) runs straight into **Chapter 4, "Units & Sizes"**, so it plays as one continuous block of roughly 37 minutes.

Colours come as names (`red`), hex (`#e11d48`), `rgb()`, or `hsl()` — the last is worth learning because adjusting a hue or lightness by hand is far easier than editing hex digits. Units matter more than they look: `px` is a fixed absolute size; `rem` is relative to the root font size, so it scales when a visitor increases their browser''s text size — which is why `rem` is the right default for font sizes and accessibility. `em` is relative to the *parent''s* size and therefore compounds when nested, which surprises people. Percentages are relative to the containing element. Rule of thumb: `rem` for type and spacing, `%` or fluid units for widths, `px` only where a genuinely fixed size is what you mean, like a 1px border.',
      'Set a page''s base font size, then size three headings in rem and one in px. Increase your browser''s default text size in its settings and observe which headings respond and which stay stubbornly fixed — that difference is a real accessibility problem.',
      '[{"question":"What is rem relative to?","options":["The parent element''s font size","The root element''s font size","The screen width","A fixed 16 pixels always"],"correct_index":1},{"question":"Why prefer rem over px for font sizes?","options":["It renders sharper","It scales when a visitor increases their browser''s text size","It is shorter to type","px is deprecated"],"correct_index":1}]'::jsonb),
    (v_m1, 'The Box Model', 'Every element is a box — content, padding, border, margin — and the one property that makes sizing behave the way you expect.', 'https://www.youtube.com/watch?v=n4R2E7O-Ngo', 5,
      array['Identify content, padding, border, and margin on an element', 'Explain how box-sizing: border-box changes width calculation', 'Inspect an element''s box model in DevTools'],
      'Watch **Chapter 5, "Box Model"** of the anchor course, roughly an hour and eleven minutes in, running about 25 minutes. It also covers default browser styles and CSS resets, which is useful context.

Every element on a page is a rectangular box with four layers: the content, `padding` inside the border, the `border` itself, and `margin` outside it holding other elements away. The classic trap: by default, setting `width: 300px` sizes only the *content*, so adding 20px of padding and a 2px border makes the element 344px wide and blows up your layout. `box-sizing: border-box` makes width mean the whole box, padding and border included, which is what everyone actually wants — which is why most stylesheets set it globally on every element as their very first rule. DevTools draws this box for you with each layer labelled; open it whenever spacing looks wrong.',
      'Make a box 300px wide with 20px padding and a 2px border. Measure its real width in DevTools, then apply box-sizing: border-box and measure again. Then set it globally on every element and see what shifts on a page you''ve already built.',
      '[{"question":"What sits between the border and other elements?","options":["Padding","Margin","Content","Outline"],"correct_index":1},{"question":"What does box-sizing: border-box do?","options":["Adds a border","Makes width include padding and border rather than content only","Removes the margin","Centres the element"],"correct_index":1}]'::jsonb),
    (v_m1, 'Styling Text with CSS', 'Making text readable — families, sizes, weight, line height, alignment, and the transform and decoration properties.', 'https://www.youtube.com/watch?v=Y5TYDo9Qcv4', 6,
      array['Set font-family with a sensible fallback stack', 'Use font-size, font-weight, and line-height to improve readability', 'Apply text-align, text-transform, and text-decoration'],
      'Back to Kevin Powell for a focused half hour on text. He starts with inheritance — which you met two lessons ago — and builds through font-family, size, weight and style, then colour, line-height, alignment, transform and decoration, with a DevTools detour along the way.

`font-family` takes a list, not a single name — the browser tries each in turn and falls back, so always end with a generic like `sans-serif` in case nothing else loads. `line-height` is the quiet win: body text at around 1.5 is dramatically easier to read than the browser default, and it costs one line of CSS. This video sticks to the fonts already available on a device; loading a custom web font from a service like Google Fonts is a separate topic, and worth being cautious about — every font file is an extra download on every visit, so a well-chosen system font stack is often the better call for an audience on limited data.',
      'Set body text to a readable size with a line-height of 1.5 and a font stack ending in a generic fallback. Then deliberately name a font that doesn''t exist as your first choice and confirm the fallback takes over.',
      '[{"question":"Why does font-family take a list of fonts?","options":["To display them all at once","The browser falls back through the list if a font isn''t available","To randomise the font","It doesn''t — only one is allowed"],"correct_index":1},{"question":"What does line-height affect?","options":["The width of the text","The vertical spacing between lines, which strongly affects readability","The font weight","The letter spacing"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Layout with Flexbox and Grid', 'Stop letting the browser decide where things go. Control the flow, lay out rows and columns with Flexbox, build real grids, and position elements deliberately.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'The Display Property: Block, Inline and Inline-Block', 'Why a div takes up a whole line and a span doesn''t — and the first tool for putting two boxes side by side.', 'https://www.youtube.com/watch?v=G3e-cpL7ofc', 1,
      array['Explain the difference between block, inline, and inline-block elements', 'Use display: inline-block to place boxes side by side', 'Fix the alignment gap that appears between inline-block elements'],
      'Watch **Chapter 8, "CSS Display Property"**, roughly two and a half hours into this full course — use the chapter list rather than scrubbing to a timestamp. Every element has a default display type. Block elements like `<div>` and `<p>` claim the full width and force a line break; inline elements like `<span>` and `<a>` sit within a line of text and ignore width and height. `inline-block` is the hybrid: it flows inline but accepts width, height, and padding, which is the old way of putting boxes next to each other. One gotcha the video covers: inline-block elements align to the text baseline by default, so boxes of different heights sit oddly until you add `vertical-align: top`. Flexbox has largely replaced this technique, but display is the foundation Flexbox sits on, and this trips people up long before they reach it.',
      'Put three coloured boxes on a page. With default display they stack vertically — switch them to inline-block and get them side by side. Then make one box taller than the others and fix the alignment.',
      '[{"question":"What does a block-level element do by default?","options":["Sits within a line of text","Takes the full available width and starts on a new line","Becomes invisible","Ignores padding"],"correct_index":1},{"question":"What can inline-block do that inline cannot?","options":["Nothing different","Accept width and height while still flowing inline","Contain text","Be clicked"],"correct_index":1}]'::jsonb),
    (v_m2, 'Flexbox: The Basics', 'One declaration turns a container into a flexible row — then you control alignment along both axes.', 'https://www.youtube.com/watch?v=u044iM9xsWU', 2,
      array['Turn a container into a flex container with display: flex', 'Control layout along the main axis with justify-content', 'Align items across the cross axis with align-items'],
      '`display: flex` on a *parent* changes how its *children* lay out — that parent/child relationship is the thing to internalise. Children become flex items in a row by default; `flex-direction: column` stacks them instead. `justify-content` positions items along the main axis (horizontally in a row) and `align-items` along the cross axis (vertically in a row). The pair swaps meaning when you change direction, which is the single most common source of confusion — when a flex rule seems backwards, check the direction first. This video also introduces `flex-grow` early, which is worth watching for: it explains *why* items expand rather than just how.',
      'Build a row of three cards with display: flex. Cycle justify-content through flex-start, center, space-between, and space-around, then set flex-direction: column and watch justify-content and align-items swap axes.',
      '[{"question":"Where do you apply display: flex?","options":["On each child item","On the parent container","On the body only","On the html element"],"correct_index":1},{"question":"In a default flex row, what does align-items control?","options":["Horizontal spacing","Vertical alignment across the cross axis","The order of items","The gap size"],"correct_index":1}]'::jsonb),
    (v_m2, 'Flexbox Layout Patterns', 'Four patterns you will reach for constantly — even columns, wrapping card rows, content with a sidebar, and pushing items apart.', 'https://www.youtube.com/watch?v=vQAvjof1oe4', 3,
      array['Build even columns and a wrapping card row with flex', 'Create a content-plus-sidebar layout', 'Push an element to the far side using auto margins'],
      'This is the practical follow-on: rather than teaching properties one at a time, it builds the layouts you''ll actually need. Even columns and wrapping card rows come from combining `flex-wrap` with `flex-basis` and `flex-grow`. The content-with-sidebar pattern is worth memorising — it''s the skeleton of a huge share of real websites. And the auto-margin trick (`margin-left: auto` on a flex item) pushes that item to the far end, which is how a logo sits left while a nav sits right. Keep the companion cheatsheet open while you work through it.',
      'Rebuild your Level 2 page''s navigation with Flexbox: logo on the left, links pushed to the right using an auto margin. Then build a row of cards that wraps onto a second line when the window narrows.',
      '[{"question":"What does margin-left: auto do to a flex item?","options":["Centres it","Pushes it to the far end of the container","Removes its margin","Hides it"],"correct_index":1},{"question":"Which property lets flex items move onto a new line?","options":["flex-grow","flex-wrap","justify-content","align-items"],"correct_index":1}]'::jsonb),
    (v_m2, 'CSS Grid: The Basics', 'Two-dimensional layout — define columns, place items on the grid, and use the browser''s grid inspector.', 'https://www.youtube.com/watch?v=rg7Fvvl3taU', 4,
      array['Create a grid with display: grid and grid-template-columns', 'Space a grid with the gap property', 'Span an item across multiple columns using line numbers'],
      'Flexbox lays out in one direction at a time; Grid works in two at once, which makes it the right tool for page-level structure. `grid-template-columns` defines your columns, and `gap` spaces everything without the margin arithmetic Flexbox sometimes needs. A genuinely useful habit from this video: mostly *don''t* declare your rows — let them be created implicitly as content arrives, and you avoid a whole category of bug where content outgrows a fixed row count. It also covers `grid-template-areas`, which lets you name regions and sketch the layout visually in your CSS. Turn on the browser''s grid inspector early; seeing the line numbers drawn over your page makes placement click.',
      'Build a three-column grid with a gap. Make one item span two columns using line numbers, then rebuild the same layout using named grid-template-areas and compare which you find more readable.',
      '[{"question":"What is the main difference between Grid and Flexbox?","options":["Grid is newer only","Grid lays out in two dimensions; Flexbox works in one at a time","Flexbox cannot use gap","Grid only works on images"],"correct_index":1},{"question":"Why is it often better not to declare grid rows explicitly?","options":["Rows are deprecated","Rows are created implicitly as content arrives, avoiding overflow bugs","It renders faster","Rows cost extra bandwidth"],"correct_index":1}]'::jsonb),
    (v_m2, 'Building a Responsive Card Grid', 'A full build — a card grid that reflows itself as the screen changes, without a single media query.', 'https://www.youtube.com/watch?v=sKFW3wek21Q', 5,
      array['Use auto-fit with minmax() to make a grid respond without media queries', 'Control image shape with aspect-ratio and object-fit', 'Make one card span wider as a featured item'],
      'This builds a real component end to end. The centrepiece is `repeat(auto-fit, minmax(...))`: instead of saying "three columns, then two on tablet, then one on mobile", you state a minimum card width and let the browser fit as many as it can. The layout then responds at every width rather than only at the breakpoints you happened to think of — genuinely less code and a better result. `aspect-ratio` and `object-fit: cover` solve the other half of the problem: keeping cards uniform when the images you''re given are all different shapes. Note this is a card grid, not a full page skeleton — for header/sidebar/footer structure, the grid-template-areas section of the previous lesson is the tool.',
      'Build a card grid with repeat(auto-fit, minmax(250px, 1fr)). Resize the browser from wide to phone-width and count how many times the column count changes — with no media queries written.',
      '[{"question":"What does repeat(auto-fit, minmax(250px, 1fr)) achieve?","options":["Exactly three columns always","As many columns as fit at a 250px minimum, responding at every width","A single column","A fixed 250px page"],"correct_index":1},{"question":"What problem does object-fit: cover solve?","options":["Slow image loading","Images of different shapes filling a uniform card space without distorting","Missing alt text","Image licensing"],"correct_index":1}]'::jsonb),
    (v_m2, 'CSS Position: Static, Relative, Absolute and Fixed', 'Take an element out of the normal flow and put it exactly where you want it.', 'https://www.youtube.com/watch?v=jx5jmI0UlXU', 6,
      array['Distinguish static, relative, absolute, and fixed positioning', 'Offset an element with top, right, bottom, and left', 'Explain what an absolutely positioned element is positioned relative to'],
      'Everything is `position: static` by default — it sits where the flow puts it and ignores `top`/`left`. `relative` nudges an element from where it would have been, while leaving its original space reserved. `absolute` removes it from the flow entirely and positions it against its nearest positioned ancestor — which is why the standard move is setting `position: relative` on a parent purely to give an absolute child something to anchor to. `fixed` pins to the viewport so the element stays put while the page scrolls. This is a fast nine-minute tour; the next lesson covers what goes wrong with these in real layouts.',
      'Place a small badge in the top-right corner of a card using position: absolute, with position: relative on the card. Then remove the relative from the card and watch the badge fly to the corner of the page.',
      '[{"question":"What is an absolutely positioned element positioned against?","options":["Always the page body","Its nearest positioned ancestor","Its immediate parent always","The viewport"],"correct_index":1},{"question":"How does relative differ from absolute?","options":["No difference","Relative keeps the element''s original space reserved in the flow; absolute removes it","Relative cannot use top/left","Absolute only works on images"],"correct_index":1}]'::jsonb),
    (v_m2, 'Positioning in the Real World', 'Containing blocks, sticky headers, and why position: fixed sometimes mysteriously stops working.', 'https://www.youtube.com/watch?v=86nTToBm2uQ', 7,
      array['Explain what a containing block is and how it governs absolute positioning', 'Build a sticky element with position: sticky', 'Identify what can break position: fixed'],
      'This picks up exactly where the basics leave off. The containing block is the concept that makes absolute positioning predictable instead of mysterious — once you can identify which ancestor an element is anchored to, the surprises stop. `position: sticky` is the one people reach for most: an element behaves normally until it hits a scroll threshold, then pins — the standard sticky page header. It needs a `top` value to work, which is the usual reason it silently does nothing. The video also covers what breaks `position: fixed`, including transforms on an ancestor, which is a genuinely hard bug to find on your own. One topic this level doesn''t cover with video: `z-index`, which controls what stacks on top when positioned elements overlap. Look it up on MDN when two elements fight over the same space.',
      'Make a page header stick to the top on scroll with position: sticky and a top value. Then remove the top value and confirm it stops working — that''s the bug you''ll hit most often.',
      '[{"question":"What does position: sticky do?","options":["Pins to the viewport immediately","Behaves normally until a scroll threshold, then pins","Removes the element from the flow","Centres the element"],"correct_index":1},{"question":"Why might position: sticky silently do nothing?","options":["It needs JavaScript","No threshold value such as top is set","It only works on images","It is deprecated"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Responsive Design and Polish', 'Most of your visitors are on a phone. Make layouts adapt to any screen, add motion that improves rather than distracts, and learn to debug CSS instead of guessing at it.', v_module_offset + 3)
  returning id into v_m3;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m3, 'Adding Your First Breakpoint', 'Take a fixed layout and make it adapt — the practical introduction to media queries.', 'https://www.youtube.com/watch?v=QGb-W-c-gIM', 1,
      array['Write a media query with a breakpoint', 'Change a layout at a given screen width', 'Test a layout at different widths using DevTools'],
      'A media query says "apply these rules only when the screen meets this condition". This lesson is deliberately practical: take a page that looks wrong on a phone, add one breakpoint, and watch it adapt. The systematic treatment of how to *choose* breakpoints comes next.

The important habit to build now is testing narrow. Open DevTools, switch to device mode, and set the width to around 360px — that is a very common phone width in Kenya and across the region, and it is far narrower than most laptop screens. A layout that only looks right at 1400px is a layout most of your visitors will never see working. Resizing the browser window by hand works just as well when you want a quick check.',
      'Take your card layout from the last module and add a media query that stacks the cards into one column below 600px. Then check it at 360px wide in DevTools device mode.',
      '[{"question":"What does a media query do?","options":["Loads a different HTML file","Applies CSS rules only when the screen meets a condition","Compresses images for mobile","Detects the user''s device brand"],"correct_index":1},{"question":"Why test your layout at around 360px wide?","options":["It is the standard desktop width","It is a very common phone width, and phones are most of your audience","CSS breaks below 400px","It makes the page load faster"],"correct_index":1}]'::jsonb),
    (v_m3, 'Mobile-First Design and Choosing Breakpoints', 'Why you write the small-screen styles first and layer up — and how to pick breakpoints that aren''t arbitrary.', 'https://www.youtube.com/watch?v=69IbzTWg5PM', 2,
      array['Explain what mobile-first means and why it produces simpler CSS', 'Choose breakpoints based on where the layout breaks', 'Use min-width queries to layer on larger-screen styles'],
      'Mobile-first means your base CSS — the rules outside any media query — describes the phone layout, and `min-width` queries then add complexity as the screen grows. It sounds like a preference; it isn''t. Writing it the other way round means every mobile visitor downloads and applies desktop rules only to have them overridden, and the CSS ends up full of rules undoing other rules. Mobile-first CSS is consistently shorter and easier to reason about.

On choosing breakpoints: don''t reach for a list of device widths, because there are hundreds of devices and the list is always out of date. Instead widen your browser slowly until the layout looks bad, and put a breakpoint there. Your content decides where the breaks belong, not a table of phone models.',
      'Rewrite one of your responsive pages mobile-first: strip the media queries, make the base styles the phone layout, then add min-width queries to build up. Compare the total line count against your original.',
      '[{"question":"In a mobile-first stylesheet, what do the base styles outside any media query describe?","options":["The desktop layout","The phone layout","Print styles","Nothing"],"correct_index":1},{"question":"How should you decide where to put a breakpoint?","options":["Copy a list of common device widths","Widen the browser until the layout looks bad, and break there","Always use 768px","Add one every 100px"],"correct_index":1}]'::jsonb),
    (v_m3, 'Fluid Sizing with min(), max() and clamp()', 'Sizes that scale smoothly with the screen instead of jumping at breakpoints.', 'https://www.youtube.com/watch?v=U9VF-4euyRo', 3,
      array['Use min() and max() to set a fluid size with a limit', 'Use clamp() for a size with a minimum, preferred, and maximum', 'Explain why fluid type reduces the need for breakpoints'],
      'Media queries change things in steps; these functions change them continuously. `min(50%, 400px)` takes whichever is smaller, giving you a width that shrinks but never exceeds 400px. `clamp(1rem, 2.5vw, 2rem)` is the one you''ll use most: a minimum, a preferred fluid value, and a maximum. Headline text sized with `clamp()` scales smoothly from phone to desktop and needs no breakpoints at all.

A neat detail from the video: you can do arithmetic inside these functions without wrapping it in `calc()`. Used well, fluid sizing removes whole blocks of media queries — but keep the minimum genuinely readable, because a headline that scales down to unreadable on a small phone is worse than one that simply wraps.',
      'Size a page heading with clamp(1.5rem, 5vw, 3rem). Resize the browser slowly from phone to desktop width and watch it scale continuously, with no breakpoint anywhere in your CSS.',
      '[{"question":"What three values does clamp() take?","options":["Start, end, duration","Minimum, preferred, maximum","Top, middle, bottom","Small, medium, large"],"correct_index":1},{"question":"How does fluid sizing differ from a media query?","options":["It doesn''t","It changes continuously with screen size rather than jumping at set widths","It only works on images","It requires JavaScript"],"correct_index":1}]'::jsonb),
    (v_m3, 'Responsive Images', 'Stop images overflowing their container and blowing out your layout on a phone.', 'https://www.youtube.com/watch?v=gn0OaxS1OdY', 4,
      array['Prevent an image overflowing with max-width: 100%', 'Explain why a fixed image width breaks a mobile layout', 'Control how an image fills its space'],
      'An image with its natural width of 1600px sitting in a 360px-wide phone screen will burst straight out of the layout and force the whole page to scroll sideways. The fix is one rule most stylesheets apply globally: `max-width: 100%` on images, so an image never exceeds its container while still shrinking freely.

There''s a bandwidth point here too, and it matters for this audience. `max-width` makes a large image *display* small, but the visitor still downloads every one of those bytes over their mobile bundle. Resizing and compressing images before you upload them is the single biggest performance win available to a beginner — often larger than everything else in this level combined.',
      'Put a large image in a narrow container and confirm it overflows and forces sideways scrolling. Add max-width: 100% and watch it behave. Then check the file''s real size and consider whether your visitor should be downloading that much.',
      '[{"question":"What does max-width: 100% do to an image?","options":["Makes it always fill the screen","Stops it exceeding its container while still allowing it to shrink","Compresses the file","Centres it"],"correct_index":1},{"question":"Does max-width: 100% reduce how much data the visitor downloads?","options":["Yes, it shrinks the file","No — the full file still downloads; only the display size changes","Only on mobile","Only for JPEGs"],"correct_index":1}]'::jsonb),
    (v_m3, 'Transitions and Timing', 'Smooth state changes instead of abrupt jumps — and which properties are cheap to animate.', 'https://www.youtube.com/watch?v=Nloq6uzF8RQ', 5,
      array['Apply a transition with duration, property, timing function, and delay', 'Write the transition shorthand', 'Explain why opacity and transform are the performant properties to animate'],
      'A transition tells the browser to move between two states over time rather than snapping. Four properties control it: `transition-property` (what changes), `transition-duration` (how long), `transition-timing-function` (the easing curve), and `transition-delay`. The shorthand combines them.

The performance point is the one to remember: animating `opacity` and `transform` is cheap because the browser can hand them to the GPU, while animating `width`, `height`, or `margin` forces it to recalculate layout on every frame — which on a low-end phone means visible stutter. Keep durations short, around 150-300ms; anything slower starts to feel sluggish rather than polished. The `transform` property itself — translate, scale, rotate — is worth exploring on your own once you''re comfortable here.',
      'Add a hover transition to a button that changes its opacity over 200ms. Then try transitioning its width instead, and compare how smooth each one feels — especially if you can test on a phone.',
      '[{"question":"Which properties are cheapest to animate?","options":["width and height","opacity and transform","margin and padding","font-size"],"correct_index":1},{"question":"What does transition-timing-function control?","options":["How long the transition lasts","The easing curve — how the change is paced","Which property changes","The delay before starting"],"correct_index":1}]'::jsonb),
    (v_m3, 'CSS Custom Properties', 'Define a value once, reuse it everywhere — and scope your variables properly instead of dumping them all at the top.', 'https://www.youtube.com/watch?v=_2LwjfYc1x8', 6,
      array['Declare a custom property and use it with var()', 'Explain the benefit of defining a value in one place', 'Scope a custom property to a component rather than :root'],
      'The basics first, since the video assumes them. You declare a custom property with two dashes — `--brand-color: #e11d48;` — usually on `:root` so it''s available everywhere, and use it with `var(--brand-color)`. Change that one line and every use updates, which is how a whole site''s colour scheme becomes a five-line edit.

Kevin Powell then pushes past the habit most tutorials stop at. Declaring every variable on `:root` works, but scoping a property to a component instead lets you create variations by changing one value on that component rather than redeclaring a pile of properties. Watch it as the follow-up to the basics above — he''s arguing against the `:root`-only pattern, so it will make far more sense once you''ve written variables the simple way yourself first.',
      'Define three colour custom properties on :root and use them across a page. Then build a card component that declares its own local custom property, and make a second variation by overriding just that one value.',
      '[{"question":"How do you use a custom property''s value?","options":["use(--name)","var(--name)","$name","@name"],"correct_index":1},{"question":"What is the advantage of scoping a custom property to a component?","options":["It loads faster","You can create variations by changing one value rather than redeclaring many properties","It works in older browsers","It avoids needing CSS at all"],"correct_index":1}]'::jsonb),
    (v_m3, 'Debugging CSS in Browser DevTools', 'Stop guessing at why a style isn''t applying — inspect it, edit it live, and see what the browser actually did.', 'https://www.youtube.com/watch?v=qnS-WAjkI18', 7,
      array['Inspect an element and read its applied styles', 'Edit CSS live in the browser to test a fix', 'Find why a rule isn''t applying by reading overridden styles'],
      'DevTools is where CSS stops being guesswork. Right-click any element, choose Inspect, and you see every rule applying to it, in order, with overridden rules struck through — which answers the "why isn''t my CSS working?" question from Level 3''s third lesson directly, by showing you the rule that beat yours.

The habit worth building: change values in DevTools first, then copy the one that works back into your file. It''s far faster than edit-save-reload, and it costs nothing when you get it wrong. Nothing you change there is permanent — a refresh throws it all away, so experiment freely. Between this and the W3C validator from Level 2, you now have a real method for both kinds of "it looks wrong and I don''t know why".',
      'Inspect an element on any website you use and find a rule that has been struck through by a more specific one. Then live-edit a colour and a padding value on your own page, and copy the values you settle on back into your stylesheet.',
      '[{"question":"What does a struck-through rule in DevTools mean?","options":["It has a syntax error","It was overridden by a more specific or later rule","It is loading slowly","It is deprecated"],"correct_index":1},{"question":"What happens to DevTools edits when you refresh the page?","options":["They are saved to your file","They are discarded","They break the page","They apply to every site"],"correct_index":1}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

end $$;
